// Package audit provides a durable audit trail for authentication,
// authorization, and future clinical operations.
//
// Recording is best-effort: a failed INSERT is logged through slog and does
// not fail the operation that triggered it. This package is
// transport-agnostic. The SQL layer is generated by sqlc (see
// db/query/audit.sql).
package audit

import (
	"context"
	"database/sql"
	"encoding/hex"
	"errors"
	"fmt"
	"log/slog"
	"strings"

	"golang.org/x/crypto/blake2b"

	"github.com/google/uuid"

	"librevita.org/internal/core/audit/repository"
	"librevita.org/internal/types"
)

// Event is one audit record. Sensitive values (passwords, tokens, CSRF)
// must never be placed in Detail. The actor_name/actor_role,
// user_agent and resource_name fields are denormalized so every row is
// a self-contained snapshot (Event Sourcing): no lookup against
// external tables is needed to rebuild the context of an event.
type Event struct {
	ActorID      string       // UUIDv7 of the user account; empty when anonymous.
	ActorMail    string       // Best-effort actor identity.
	ActorName    string       // Denormalized actor display name.
	ActorRole    string       // Denormalized actor role name.
	UserAgent    string       // Client user agent of the request.
	Action       string       // e.g. "register", "login", "logout", "authorize".
	Resource     string       // e.g. "user", "session", "policy:admin.view".
	ResourceName string       // Denormalized human-readable resource name.
	Result       types.AuditResult // AuditResultSuccess or AuditResultFailure.
	IP           string
	RequestID    string
	Detail       string
}

// Logger persists audit events to SQLite.
type Logger struct {
	db      *sql.DB
	queries *repository.Queries
	log     *slog.Logger
}

// NewLogger is the Fx provider. It requires the SQLite backend, like the
// session store.
func NewLogger(db *sql.DB, log *slog.Logger) (*Logger, error) {
	if db == nil {
		return nil, fmt.Errorf("audit: requires the SQLite backend")
	}
	return &Logger{db: db, queries: repository.New(db), log: log}, nil
}

// EventRow is a stored audit event with its cursor id.
type EventRow struct {
	ID         int64
	CreatedAt  types.DateTime
	ActorID    *string
	ActorEmail *string
	Action     string
	Resource   string
	Result     string
	Detail     *string
}

// Recent returns the latest audit events, newest first. A non-zero before
// acts as an exclusive id cursor for pagination.
func (l *Logger) Recent(ctx context.Context, limit int, before int64) ([]EventRow, error) {
	if before > 0 {
		rows, err := l.queries.ListAuditEventsBefore(ctx, repository.ListAuditEventsBeforeParams{
			ID: before, Limit: int64(limit),
		})
		if err != nil {
			return nil, fmt.Errorf("audit: recent before: %w", err)
		}
		return eventsFromBefore(rows), nil
	}
	rows, err := l.queries.ListRecentAuditEvents(ctx, int64(limit))
	if err != nil {
		return nil, fmt.Errorf("audit: recent: %w", err)
	}
	return eventsFromRecent(rows), nil
}

// ForResource returns the events recorded against a resource (e.g.
// "patient:<id>"), newest first, limited to the most recent rows.
func (l *Logger) ForResource(ctx context.Context, resource string, limit int) ([]EventRow, error) {
	rows, err := l.queries.ListAuditEventsForResource(ctx, repository.ListAuditEventsForResourceParams{
		Resource: resource, Limit: int64(limit),
	})
	if err != nil {
		return nil, fmt.Errorf("audit: for resource %s: %w", resource, err)
	}
	return eventsFromResource(rows), nil
}

func eventsFromRecent(rows []repository.ListRecentAuditEventsRow) []EventRow {
	out := make([]EventRow, 0, len(rows))
	for _, r := range rows {
		out = append(out, EventRow{ID: r.ID, CreatedAt: r.CreatedAt, ActorID: uuidOrEmptyPtr(r.ActorID),
			ActorEmail: r.ActorEmail, Action: r.Action, Resource: r.Resource,
			Result: r.Result, Detail: r.Detail})
	}
	return out
}

func eventsFromBefore(rows []repository.ListAuditEventsBeforeRow) []EventRow {
	out := make([]EventRow, 0, len(rows))
	for _, r := range rows {
		out = append(out, EventRow{ID: r.ID, CreatedAt: r.CreatedAt, ActorID: uuidOrEmptyPtr(r.ActorID),
			ActorEmail: r.ActorEmail, Action: r.Action, Resource: r.Resource,
			Result: r.Result, Detail: r.Detail})
	}
	return out
}

func eventsFromResource(rows []repository.ListAuditEventsForResourceRow) []EventRow {
	out := make([]EventRow, 0, len(rows))
	for _, r := range rows {
		out = append(out, EventRow{ID: r.ID, CreatedAt: r.CreatedAt, ActorID: uuidOrEmptyPtr(r.ActorID),
			ActorEmail: r.ActorEmail, Action: r.Action, Resource: r.Resource,
			Result: r.Result, Detail: r.Detail})
	}
	return out
}

// Record persists ev with a BLAKE2b hash chained to the previous entry:
// each row carries the digest of the preceding hash plus its own
// payload, so any modification of an existing entry breaks the chain
// for every following row. The read-hash + insert runs inside one
// transaction so concurrent writers cannot interleave. Failures are
// logged and swallowed so that auditing never breaks the audited
// operation.
func (l *Logger) Record(ctx context.Context, ev Event) {
	// The result set is closed by the database CHECK constraint and by
	// this enum; an unknown value is a programming error and must not
	// reach the trail.
	if !ev.Result.Valid() {
		l.log.Error("audit record failed",
			"action", ev.Action, "resource", ev.Resource, "result", ev.Result,
			"error", "invalid result value")
		return
	}
	// The event time is authoritative for auditing, so the application
	// generates it (not the database DEFAULT) and includes it in the
	// signed payload.
	createdAt := types.Now()
	tx, err := l.db.BeginTx(ctx, nil)
	if err != nil {
		l.log.Error("audit record failed", "action", ev.Action, "error", err)
		return
	}
	queries := repository.New(tx)
	committed := false
	defer func() {
		if !committed {
			_ = tx.Rollback()
		}
	}()

	prev := ""
	prevSig, err := queries.GetLastAuditSignature(ctx)
	if err != nil && !errors.Is(err, sql.ErrNoRows) {
		l.log.Error("audit record failed", "action", ev.Action, "error", err)
		return
	}
	if err == nil {
		prev = prevSig
	}
	err = queries.CreateAuditEvent(ctx, repository.CreateAuditEventParams{
		ActorID:      uuidPtr(ev.ActorID),
		ActorEmail:   strPtr(ev.ActorMail),
		ActorName:    ev.ActorName,
		ActorRole:    ev.ActorRole,
		UserAgent:    ev.UserAgent,
		Action:       ev.Action,
		Resource:     ev.Resource,
		ResourceName: ev.ResourceName,
		Result:       ev.Result.String(),
		Ip:           strPtr(ev.IP),
		RequestID:    strPtr(ev.RequestID),
		Detail:       strPtr(ev.Detail),
		CreatedAt:    createdAt,
		Signature:    chainHash(prev, ev, createdAt),
	})
	if err != nil {
		l.log.Error("audit record failed",
			"action", ev.Action, "resource", ev.Resource, "error", err)
		return
	}
	if err := tx.Commit(); err != nil {
		l.log.Error("audit record failed", "action", ev.Action, "error", err)
		return
	}
	committed = true
}

// VerifyChain recomputes the hash chain over the whole trail and returns
// the id of the first entry whose hash does not match, or zero when the
// chain is intact. A broken chain means an entry was modified or
// reordered after it was written.
func (l *Logger) VerifyChain(ctx context.Context) (int64, error) {
	rows, err := l.queries.ListAuditChain(ctx)
	if err != nil {
		return 0, fmt.Errorf("audit: verify chain: %w", err)
	}
	var prev string
	for _, r := range rows {
		want := chainHash(prev, eventFromRow(r), r.CreatedAt)
		if r.Signature != want {
			return r.ID, nil
		}
		prev = r.Signature
	}
	return 0, nil
}

// eventFromRow rebuilds the Event that produced the stored row, so the
// signature payload can be recomputed.
func eventFromRow(r repository.ListAuditChainRow) Event {
	return Event{
		ActorID:      uuidOrEmpty(r.ActorID),
		ActorMail:    orEmpty(r.ActorEmail),
		ActorName:    r.ActorName,
		ActorRole:    r.ActorRole,
		UserAgent:    r.UserAgent,
		Action:       r.Action,
		Resource:     r.Resource,
		ResourceName: r.ResourceName,
		Result:       types.AuditResult(r.Result),
		IP:           orEmpty(r.Ip),
		RequestID:    orEmpty(r.RequestID),
		Detail:       orEmpty(r.Detail),
	}
}

// esc prevents delimiter injection: a literal "|" inside a field is
// escaped to "\|" so crafted values cannot shift the payload blocks.
func esc(v string) string {
	return strings.ReplaceAll(v, "|", "\\|")
}

// chainPayload serializes the event fields and the event time with the
// delimiter, so the signature covers every value the application
// controls. The id (generated by the database) is excluded.
func chainPayload(ev Event, createdAt types.DateTime) string {
	return esc(ev.ActorID) + "|" + esc(ev.ActorMail) + "|" + esc(ev.ActorName) + "|" +
		esc(ev.ActorRole) + "|" + esc(ev.UserAgent) + "|" + esc(ev.Action) + "|" +
		esc(ev.Resource) + "|" + esc(ev.ResourceName) + "|" + esc(ev.Result.String()) + "|" +
		esc(ev.IP) + "|" + esc(ev.RequestID) + "|" + esc(ev.Detail) + "|" + esc(createdAt.String())
}

// chainHash digests the previous signature plus the new payload with
// BLAKE2b.
func chainHash(prev string, ev Event, createdAt types.DateTime) string {
	sum := blake2b.Sum256([]byte(prev + "|" + chainPayload(ev, createdAt)))
	return hex.EncodeToString(sum[:])
}

func orEmpty(s *string) string {
	if s == nil {
		return ""
	}
	return *s
}

func strPtr(s string) *string {
	if s == "" {
		return nil
	}
	return &s
}

// uuidPtr converts the public string id to the uuid type used by the
// storage layer; an empty actor id (anonymous event) stays Nil.
func uuidPtr(s string) uuid.UUID {
	if s == "" {
		return uuid.Nil
	}
	return uuid.MustParse(s)
}

// uuidOrEmpty converts a stored uuid back to the public string form.
func uuidOrEmpty(u uuid.UUID) string {
	if u == uuid.Nil {
		return ""
	}
	return u.String()
}

// uuidOrEmptyPtr is uuidOrEmpty for the pointer-based EventRow id.
func uuidOrEmptyPtr(u uuid.UUID) *string {
	if u == uuid.Nil {
		return nil
	}
	s := u.String()
	return &s
}
